// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract MultiTokenSale {
    address public owner;
    bool public paused;

    struct TokenInfo {
        uint256 price;   // tokens por 1 BNB (tBNB)
        bool exists;
        uint256 alertThreshold; // limite mínimo para alerta
    }

    mapping(address => TokenInfo) public tokens;

    event TokenAdded(address indexed token, uint256 price, uint256 alertThreshold);
    event TokenRemoved(address indexed token);
    event TokenPriceUpdated(address indexed token, uint256 newPrice);
    event TokenAlertThresholdUpdated(address indexed token, uint256 newThreshold);
    event TokensPurchased(address indexed buyer, address indexed token, uint256 amountPaid, uint256 tokensSent);
    event Paused();
    event Unpaused();

    modifier onlyOwner() {
        require(msg.sender == owner, "Somente o dono");
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "Contrato pausado");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    function pause() external onlyOwner {
        paused = true;
        emit Paused();
    }

    function unpause() external onlyOwner {
        paused = false;
        emit Unpaused();
    }

    function addToken(address tokenAddress, uint256 price, uint256 alertThreshold) external onlyOwner {
        require(tokenAddress != address(0), "Endereco invalido");
        require(price > 0, "Preco deve ser > 0");
        tokens[tokenAddress] = TokenInfo(price, true, alertThreshold);
        emit TokenAdded(tokenAddress, price, alertThreshold);
    }

    function removeToken(address tokenAddress) external onlyOwner {
        require(tokens[tokenAddress].exists, "Token nao cadastrado");
        delete tokens[tokenAddress];
        emit TokenRemoved(tokenAddress);
    }

    function updatePrice(address tokenAddress, uint256 newPrice) external onlyOwner {
        require(tokens[tokenAddress].exists, "Token nao cadastrado");
        require(newPrice > 0, "Preco deve ser > 0");
        tokens[tokenAddress].price = newPrice;
        emit TokenPriceUpdated(tokenAddress, newPrice);
    }

    function updateAlertThreshold(address tokenAddress, uint256 newThreshold) external onlyOwner {
        require(tokens[tokenAddress].exists, "Token nao cadastrado");
        tokens[tokenAddress].alertThreshold = newThreshold;
        emit TokenAlertThresholdUpdated(tokenAddress, newThreshold);
    }

    function buyTokens(address tokenAddress) external payable whenNotPaused {
        require(tokens[tokenAddress].exists, "Token nao suportado");
        require(msg.value > 0, "Envie tBNB para comprar");

        TokenInfo memory tokenInfo = tokens[tokenAddress];
        uint256 tokensToSend = msg.value * tokenInfo.price;

        IERC20 token = IERC20(tokenAddress);
        uint256 contractBalance = token.balanceOf(address(this));
        require(contractBalance >= tokensToSend, "Tokens insuficientes no contrato");

        bool sent = token.transfer(msg.sender, tokensToSend);
        require(sent, "Falha na transferencia");

        // Se saldo baixo, emitir evento de alerta
        if (contractBalance - tokensToSend <= tokenInfo.alertThreshold) {
            emit TokenAlert(tokenAddress, contractBalance - tokensToSend);
        }

        emit TokensPurchased(msg.sender, tokenAddress, msg.value, tokensToSend);
    }

    event TokenAlert(address indexed token, uint256 currentBalance);

    // Saque de BNB
    function withdrawBNB(uint256 amount) external onlyOwner {
        require(amount <= address(this).balance, "Saldo insuficiente");
        payable(owner).transfer(amount);
    }

    // Saque de tokens
    function withdrawTokens(address tokenAddress, uint256 amount) external onlyOwner {
        IERC20 token = IERC20(tokenAddress);
        require(token.transfer(owner, amount), "Falha no saque");
    }

    // Recebe tBNB direto
    receive() external payable {}
}

